EVPI = ("# Екі нұсқа, екі мүмкін әлем (жүктеме төмен/жоғары). Мәндер - бизнес пайдасы (шартты бірлік).\n"
        "p_high = 0.3\n"
        "value = {\n"
        "    'қарапайым монолит': {'төмен': 100, 'жоғары': 20},\n"
        "    'масштабталатын':    {'төмен': 70,  'жоғары': 90},\n"
        "}\n"
        "P = {'төмен': 1 - p_high, 'жоғары': p_high}\n\n"
        "ev = {o: sum(P[w] * v for w, v in vals.items()) for o, vals in value.items()}\n"
        "best_now = max(ev, key=ev.get)\n"
        "print('күтілетін мәндер:', {o: round(x, 1) for o, x in ev.items()}, '-> қазір таңдау:', best_now)\n\n"
        "# Толық ақпарат болса: әр әлемде сол әлемге ең жақсы нұсқаны таңдар едік\n"
        "ev_perfect = sum(P[w] * max(value[o][w] for o in value) for w in P)\n"
        "evpi = ev_perfect - ev[best_now]\n"
        "print(f'толық ақпараттың құны (EVPI): {evpi:.1f}')\n"
        "prototype_cost = 5\n"
        "print('прототип (жүктеме тесті) жасау керек пе:', 'иә' if evpi > prototype_cost else 'жоқ')")

