WSJF = ("jobs = {  # атауы: (кешігу құны аптасына, ұзақтық апта)\n"
        "    'төлем қатесін түзету': (50, 1),\n"
        "    'жаңа есептер':         (30, 3),\n"
        "    'техникалық қарыз':     (12, 2),\n"
        "    'үлкен қайта жазу':     (40, 8),\n"
        "}\n\n"
        "def total_delay_cost(order):\n"
        "    t = cost = 0\n"
        "    for name in order:\n"
        "        w, d = jobs[name]\n"
        "        t += d\n"
        "        cost += w * t          # жұмыс аяқталғанша әр апта w жоғалады\n"
        "    return cost\n\n"
        "by_wsjf = sorted(jobs, key=lambda j: -jobs[j][0] / jobs[j][1])\n"
        "by_value = sorted(jobs, key=lambda j: -jobs[j][0])\n"
        "by_short = sorted(jobs, key=lambda j: jobs[j][1])\n"
        "for name, order in [('WSJF (w/d)', by_wsjf), ('тек құн', by_value), ('тек қысқасы', by_short)]:\n"
        "    print(f'{name:12} {order} -> шығын {total_delay_cost(order)}')")

